// ADR-0020 Decision 1 — provider selection is config-driven, never
// hardcoded. Every threshold/retry/timeout value here is also a config
// value (Decisions 4-6), not a literal buried in node logic.
const lead = $json.lead || {};
const workflowExecutionId = $json.workflowExecutionId;

function num(name, fallback) {
  const raw = $env[name];
  const n = Number(raw);
  return raw !== undefined && raw !== '' && Number.isFinite(n) ? n : fallback;
}

return [{
  json: {
    lead,
    workflowExecutionId,
    provider: String($env.AI_PROVIDER || 'ollama').trim().toLowerCase(),
    promptVersion: $env.AI_PROMPT_VERSION || 'v1',
    maxRetries: num('AI_MAX_RETRIES', 3),
    confidenceHigh: num('AI_CONFIDENCE_HIGH_THRESHOLD', 0.75),
    confidenceMedium: num('AI_CONFIDENCE_MEDIUM_THRESHOLD', 0.4),
    ollamaBaseUrl: $env.OLLAMA_BASE_URL || 'http://127.0.0.1:11434',
    ollamaModel: $env.OLLAMA_MODEL || 'qwen2.5-coder:7b',
    ollamaTimeoutMs: num('AI_OLLAMA_TIMEOUT_MS', 300000),
    startedAt: Date.now(),
  },
}];

// ADR-0020 Decision 2 — the prompt is never embedded in a node; it's read
// from the versioned file (mounted read-only, see docker-compose.yml) and
// parameterized here with the lead's own fields.
const config = $('Load Config').item.json;
const fileContent = Buffer.from($input.item.binary.data.data, 'base64').toString('utf8');
const lead = config.lead;

function fill(template, vars) {
  return template.replace(/\{\{\s*(\w+)\s*\}\}/g, (_, key) => {
    const v = vars[key];
    return (v === undefined || v === null || v === '') ? 'Unknown' : String(v);
  });
}

const promptText = fill(fileContent, {
  contactName: lead.contactName,
  email: lead.email,
  phone: lead.phone,
  company: lead.company,
  industry: lead.industry,
  companySize: lead.companySize,
  source: lead.source,
  createdAt: lead.createdAt,
});

return [{
  json: {
    promptText,
    model: config.ollamaModel,
    provider: config.provider,
    promptVersion: config.promptVersion,
    lead: config.lead,
    workflowExecutionId: config.workflowExecutionId,
    maxRetries: config.maxRetries,
    confidenceHigh: config.confidenceHigh,
    confidenceMedium: config.confidenceMedium,
    ollamaBaseUrl: config.ollamaBaseUrl,
    ollamaTimeoutMs: config.ollamaTimeoutMs,
    retryCount: 0,
    startedAt: config.startedAt,
  },
}];

// Stable re-entry point for the retry loop (ADR-0020 Decision 5) — both
// the first attempt (from Build Initial Prompt) and every retry (from
// Prepare Retry) flow through here, so downstream nodes can always read
// "the state used for this attempt" via $('Prepare Attempt').item.json,
// regardless of which upstream branch produced it.
return [{ json: { ...$json } }];

// ADR-0020 Decision 8 -- three failure classes, classified here:
// schema-invalid (parses but fails validation, or isn't JSON at all),
// transient (network/timeout/5xx -- retryable), definitive (4xx the
// provider itself rejected -- not retryable). 'valid' is the happy path.
const attempt = $('Prepare Attempt').item.json;
const response = $json;

function extractJson(text) {
  if (typeof text !== 'string') return null;
  let cleaned = text.trim();
  cleaned = cleaned.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  try {
    return JSON.parse(cleaned);
  } catch (e) {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) {
      try { return JSON.parse(match[0]); } catch (e2) { return null; }
    }
    return null;
  }
}

const PRIORITIES = ['LOW', 'MEDIUM', 'HIGH', 'URGENT'];
const LEVELS = ['LOW', 'MEDIUM', 'HIGH'];
const TIMELINES = ['IMMEDIATE', 'SHORT_TERM', 'MEDIUM_TERM', 'LONG_TERM', 'UNKNOWN'];

function validateSchema(obj) {
  if (!obj || typeof obj !== 'object') return 'Response is not a JSON object.';
  if (typeof obj.leadScore !== 'number' || obj.leadScore < 0 || obj.leadScore > 100) return 'leadScore must be a number 0-100.';
  if (typeof obj.confidence !== 'number' || obj.confidence < 0 || obj.confidence > 1) return 'confidence must be a number 0.0-1.0.';
  if (!PRIORITIES.includes(obj.priority)) return `priority must be one of: ${PRIORITIES.join(', ')}.`;
  if (obj.buyingIntent != null && !LEVELS.includes(obj.buyingIntent)) return 'buyingIntent invalid.';
  if (obj.urgency != null && !LEVELS.includes(obj.urgency)) return 'urgency invalid.';
  if (obj.riskLevel != null && !LEVELS.includes(obj.riskLevel)) return 'riskLevel invalid.';
  if (obj.estimatedTimeline != null && !TIMELINES.includes(obj.estimatedTimeline)) return 'estimatedTimeline invalid.';
  if (obj.decisionMakerIdentified != null && typeof obj.decisionMakerIdentified !== 'boolean') return 'decisionMakerIdentified must be boolean.';
  if (obj.painPoints != null && !Array.isArray(obj.painPoints)) return 'painPoints must be an array.';
  if (typeof obj.recommendedAction !== 'string' || !obj.recommendedAction.trim()) return 'recommendedAction is required.';
  if (typeof obj.summary !== 'string' || !obj.summary.trim()) return 'summary is required.';
  if (typeof obj.reasoning !== 'string' || !obj.reasoning.trim()) return 'reasoning is required.';
  if (obj.budgetEstimate != null) {
    const b = obj.budgetEstimate;
    if (typeof b !== 'object' || typeof b.min !== 'number' || typeof b.max !== 'number' || typeof b.currency !== 'string') {
      return 'budgetEstimate, if present, must be { min, max, currency }.';
    }
  }
  return null;
}

let outcome;
let reason = null;
let parsed = null;

if (response && response.error) {
  const message = String((response.error && response.error.message) || response.error || '');
  const httpCodeMatch = message.match(/\b(4\d\d)\b/);
  const httpCode = (response.error && response.error.httpCode) || (httpCodeMatch ? httpCodeMatch[1] : null);
  const isDefinitive = httpCode && ['400', '401', '403', '404'].includes(String(httpCode));
  outcome = isDefinitive ? 'definitive' : 'transient';
  reason = message || 'AI provider call failed.';
} else {
  const content = response && response.message && response.message.content;
  parsed = extractJson(content);
  if (parsed === null) {
    outcome = 'schema_invalid';
    reason = 'Model response was not valid JSON.';
  } else {
    const validationError = validateSchema(parsed);
    if (validationError) {
      outcome = 'schema_invalid';
      reason = validationError;
    } else {
      outcome = 'valid';
    }
  }
}

return [{
  json: {
    ...attempt,
    outcome,
    reason,
    parsed,
    rawModelOutput: (response && response.message) ? response.message.content : null,
    latencyMs: Date.now() - attempt.startedAt,
  },
}];

// ADR-0020 Decision 6 -- three-tier confidence policy, thresholds are
// config values (Load Config), never hardcoded here.
const item = $json;
const parsed = item.parsed;
const confidence = parsed.confidence;

let tier;
if (confidence >= item.confidenceHigh) tier = 'HIGH';
else if (confidence >= item.confidenceMedium) tier = 'MEDIUM';
else tier = 'LOW';

const needsManualReview = tier === 'LOW';
const annotation = tier === 'MEDIUM' ? ' [AI-assisted, review recommended]' : '';

const budget = parsed.budgetEstimate || null;

return [{
  json: {
    contractVersion: '1',
    workflowExecutionId: item.workflowExecutionId,
    workflowName: '03-ai-qualification',
    provider: item.provider,
    model: item.model,
    promptVersion: item.promptVersion,
    leadScore: Math.round(parsed.leadScore),
    confidence,
    priority: parsed.priority,
    industry: parsed.industry || undefined,
    companySizeEstimate: parsed.companySizeEstimate || undefined,
    budgetEstimateMin: budget ? budget.min : undefined,
    budgetEstimateMax: budget ? budget.max : undefined,
    budgetEstimateCurrency: budget ? budget.currency : undefined,
    buyingIntent: parsed.buyingIntent || undefined,
    urgency: parsed.urgency || undefined,
    decisionMakerIdentified: parsed.decisionMakerIdentified,
    estimatedTimeline: parsed.estimatedTimeline || undefined,
    riskLevel: parsed.riskLevel || undefined,
    painPoints: parsed.painPoints || [],
    recommendedAction: `${parsed.recommendedAction}${annotation}`,
    summary: parsed.summary,
    reasoning: parsed.reasoning,
    needsManualReview,
    durationMs: item.latencyMs,
    leadId: item.lead.id,
  },
}];

// ADR-0020 Decision 5 -- a schema-invalid retry feeds the model its own
// bad output plus the specific validation error; a transient retry just
// resends the same prompt.
const item = $json;
const nextRetryCount = item.retryCount + 1;

let promptText = item.promptText;
if (item.outcome === 'schema_invalid') {
  promptText = `${item.promptText}\n\n---\nYour previous response was rejected: ${item.reason}\nYour previous raw output was:\n${item.rawModelOutput || '(no output captured)'}\n\nReturn ONLY a corrected, valid JSON object matching the required schema. No prose, no markdown fences.`;
}

return [{
  json: {
    promptText,
    model: item.model,
    provider: item.provider,
    promptVersion: item.promptVersion,
    lead: item.lead,
    workflowExecutionId: item.workflowExecutionId,
    maxRetries: item.maxRetries,
    confidenceHigh: item.confidenceHigh,
    confidenceMedium: item.confidenceMedium,
    ollamaBaseUrl: item.ollamaBaseUrl,
    ollamaTimeoutMs: item.ollamaTimeoutMs,
    retryCount: nextRetryCount,
    startedAt: item.startedAt,
  },
}];

// ADR-0020 Decision 8 -- every failure class (retries exhausted, or a
// definitive provider rejection) still writes back through the SAME
// qualification contract, flagged for manual review. Never leaves a lead
// stuck at VALIDATED (TDD Section 8, 'never strand a lead').
const item = $json;
const isDefinitive = item.outcome === 'definitive';
const retryCount = item.retryCount || 0;

return [{
  json: {
    contractVersion: '1',
    workflowExecutionId: item.workflowExecutionId,
    workflowName: '03-ai-qualification',
    provider: item.provider,
    model: item.model,
    promptVersion: item.promptVersion,
    leadScore: 0,
    confidence: 0,
    priority: 'MEDIUM',
    painPoints: [],
    recommendedAction: 'Manual review required -- automated AI qualification did not complete successfully.',
    summary: `AI qualification failed for ${item.lead.contactName} (${item.outcome}).`,
    reasoning: item.reason || 'Unknown failure.',
    needsManualReview: true,
    errorMessage: `[${item.outcome}] ${item.reason || 'Unknown failure.'}${isDefinitive ? '' : ` (after ${retryCount} retr${retryCount === 1 ? 'y' : 'ies'})`}`,
    durationMs: Date.now() - item.startedAt,
    leadId: item.lead.id,
  },
}];

// ADR-0020 Decision 1 -- OpenAI/Claude/Gemini are architecturally
// supported (Select Provider is config-driven, not hardcoded) but have no
// implemented branch this sprint. Landing here is a real, deliberate
// definitive-failure outcome for an unconfigured provider -- not a fake
// implementation standing in for one.
const config = $json;

return [{
  json: {
    contractVersion: '1',
    workflowExecutionId: config.workflowExecutionId,
    workflowName: '03-ai-qualification',
    provider: config.provider,
    model: 'n/a',
    promptVersion: config.promptVersion,
    leadScore: 0,
    confidence: 0,
    priority: 'MEDIUM',
    painPoints: [],
    recommendedAction: 'Manual review required -- no AI provider implementation is configured for this value.',
    summary: `AI qualification skipped for ${config.lead.contactName} -- unsupported AI_PROVIDER.`,
    reasoning: `AI_PROVIDER="${config.provider}" has no implemented provider branch in this workflow (only "ollama" is implemented this sprint -- see ADR-0020 Decision 1, docs/adrs/ADR-0007).`,
    needsManualReview: true,
    errorMessage: `Unsupported AI_PROVIDER: ${config.provider}`,
    durationMs: 0,
    leadId: config.lead.id,
  },
}];
